// 切割單字（自動去除多餘空白）後反轉
// 時間複雜度: O(n)，空間複雜度: O(n)
function reverseWords(s) {
    return s.trim().split(/\s+/).reverse().join(' ');
}

solutions.python:
# 方法一：內建函數（最簡潔）
class Solution:
    def reverseWords(self, s: str) -> str:
        # split() 不帶參數會自動忽略連續空白與前後空白
        return ' '.join(s.split()[::-1])


# 方法二：手動雙指標（不依賴內建 split，展現基本功）
class Solution:
    def reverseWords(self, s: str) -> str:
        words = []
        i, n = 0, len(s)
        while i < n:
            # 跳過空格
            while i < n and s[i] == ' ':
                i += 1
            if i >= n:
                break
            # 讀取一個完整單詞
            start = i
            while i < n and s[i] != ' ':
                i += 1
            words.append(s[start:i])

        # 反轉單詞順序
        return ' '.join(reversed(words))

